// Versión 1: el estado queda a la vista de todos
const deposito = { stock: { harina: 10, azucar: 4 } };

function retirar(dep, sku, cantidad) {
  if (cantidad > dep.stock[sku]) throw new Error('No alcanza ' + sku);
  dep.stock[sku] -= cantidad;
}

retirar(deposito, 'harina', 3);
console.log('harina:', deposito.stock.harina);

// Otro módulo, escrito por otra persona, «corrige» el stock por su cuenta:
deposito.stock.azucar = -2;          // nada lo impide
deposito.stock.harina = 'diez';      // tampoco esto
console.log('azúcar:', deposito.stock.azucar);

retirar(deposito, 'harina', 1);      // la función no se queja...
console.log('harina:', deposito.stock.harina);

// Versión 2: una clausura. El stock vive adentro de crearDeposito y nadie más lo ve.
function crearDeposito() {
  const stock = new Map();                 // privado: solo lo ven las funciones de abajo

  function validar(n) {
    if (!Number.isInteger(n) || n <= 0) throw new RangeError('La cantidad debe ser un entero positivo');
  }

  return {                                 // lo único que sale: la interfaz pública
    ingresar(sku, n) {
      validar(n);
      stock.set(sku, (stock.get(sku) ?? 0) + n);
    },
    retirar(sku, n) {
      validar(n);
      const hay = stock.get(sku) ?? 0;
      if (n > hay) throw new Error('No alcanza ' + sku + ': hay ' + hay + ', pediste ' + n);
      stock.set(sku, hay - n);
    },
    cuanto(sku) {
      return stock.get(sku) ?? 0;
    },
  };
}

const d = crearDeposito();
d.ingresar('harina', 10);
d.retirar('harina', 3);
console.log('harina:', d.cuanto('harina'));
console.log('¿se ve el stock desde afuera?', d.stock);          // undefined: no está en la interfaz

for (const intento of [() => d.retirar('harina', 99), () => d.ingresar('harina', -5), () => d.ingresar('harina', 2.5)]) {
  try { intento(); } catch (e) { console.log(e.name + ': ' + e.message); }
}
console.log('harina sigue en:', d.cuanto('harina'));

