Una solución posible, corrida en Node 22.23:
function crearDeposito() {
  const stock = new Map();
  const reservado = new Map();
  const hay = sku => stock.get(sku) ?? 0;
  const apartado = sku => reservado.get(sku) ?? 0;
  const disponible = sku => hay(sku) - apartado(sku);
  const entero = n => {
    if (!Number.isInteger(n) || n <= 0) throw new RangeError('La cantidad debe ser un entero positivo');
  };

  return {
    ingresar(sku, n) { entero(n); stock.set(sku, hay(sku) + n); },
    reservar(sku, n) {
      entero(n);
      if (n > disponible(sku)) throw new Error('No alcanza ' + sku + ': disponibles ' + disponible(sku) + ', pediste ' + n);
      reservado.set(sku, apartado(sku) + n);
    },
    liberar(sku, n) {
      entero(n);
      if (n > apartado(sku)) throw new RangeError('No hay tanto reservado de ' + sku);
      reservado.set(sku, apartado(sku) - n);
    },
    retirar(sku, n) {
      entero(n);
      if (n > disponible(sku)) throw new Error('No alcanza ' + sku + ': disponibles ' + disponible(sku) + ', pediste ' + n);
      stock.set(sku, hay(sku) - n);
    },
    disponible,
  };
}

const d = crearDeposito();
d.ingresar('arroz', 10);
d.reservar('arroz', 4);
console.log('disponible:', d.disponible('arroz'));
try { d.reservar('arroz', 7); } catch (e) { console.log(e.message); }
d.retirar('arroz', 5);
console.log('Se retiraron 5; disponible:', d.disponible('arroz'));
La salida es: «disponible: 6», el error «No alcanza arroz: disponibles 6, pediste 7» y «Se retiraron 5; disponible: 1». Lo importante: el invariante («reservado ≤ stock») se cuida en tres operaciones y nadie de afuera puede saltearlas, porque los dos `Map` no salen de `crearDeposito`.

