// Versión 3: una clase con campos privados (#). Mismo contrato, privacidad que impone el lenguaje.
class Deposito {
  #stock = new Map();

  #validar(n) {
    if (!Number.isInteger(n) || n <= 0) throw new RangeError('La cantidad debe ser un entero positivo');
  }

  ingresar(sku, n) {
    this.#validar(n);
    this.#stock.set(sku, (this.#stock.get(sku) ?? 0) + n);
  }

  retirar(sku, n) {
    this.#validar(n);
    const hay = this.#stock.get(sku) ?? 0;
    if (n > hay) throw new Error('No alcanza ' + sku + ': hay ' + hay + ', pediste ' + n);
    this.#stock.set(sku, hay - n);
  }

  cuanto(sku) { return this.#stock.get(sku) ?? 0; }

  inventarioConFuga() { return this.#stock; }              // entrega el Map de adentro
  inventario() { return new Map(this.#stock); }            // entrega una copia
}

const d = new Deposito();
d.ingresar('harina', 10);

const copia = d.inventario();
copia.set('harina', -50);                                  // se rompe la copia, no el depósito
console.log('con copia   :', d.cuanto('harina'));

const interno = d.inventarioConFuga();
interno.set('harina', -50);                                // se rompe el depósito por dentro
console.log('con fuga    :', d.cuanto('harina'));

// El contrato dice «kilos». ¿Qué guarda el depósito por dentro?
class GranelFlotante {                       // implementación A: kilos como decimales
  #kg = 0;
  ingresar(kg) { this.#kg += kg; }
  retirar(kg) {
    if (kg > this.#kg) throw new Error('No alcanza: hay ' + this.#kg + ' kg, pediste ' + kg);
    this.#kg -= kg;
  }
  get kilos() { return this.#kg; }
}

class GranelEnGramos {                       // implementación B: gramos enteros; la interfaz no cambia
  #g = 0;
  ingresar(kg) { this.#g += Math.round(kg * 1000); }
  retirar(kg) {
    const g = Math.round(kg * 1000);
    if (g > this.#g) throw new Error('No alcanza: hay ' + this.#g / 1000 + ' kg, pediste ' + kg);
    this.#g -= g;
  }
  get kilos() { return this.#g / 1000; }
}

for (const Clase of [GranelFlotante, GranelEnGramos]) {
  const d = new Clase();
  d.ingresar(0.3);
  d.retirar(0.1);
  try {
    d.retirar(0.2);                          // 0,3 − 0,1 − 0,2: tendría que quedar exactamente en cero
    console.log(Clase.name + ': quedan', d.kilos, 'kg');
  } catch (e) {
    console.log(Clase.name + ': ' + e.message);
  }
}
